-- 2026-01-01 - Living by Faith, Not by Sight
INSERT INTO daily_devotions (
  devotion_date,
  title,
  theme,
  key_verse_reference,
  key_verse_book,
  key_verse_chapter,
  key_verse_number,
  key_verse_text,
  devotional_text,
  today_challenge,
  prayer_starter,
  monthly_theme,
  difficulty_level,
  target_audience
) VALUES (
  '2026-01-01',
  'Living by Faith, Not by Sight',
  'Faith',
  '1 Chronicles 1:1',
  '1 Chronicles',
  1,
  1,
  '[Verse text from 1 Chronicles 1:1]',
  'Today we turn to 1 Chronicles 1, a passage rich with practical wisdom for our daily walk with God.

Recognize that your role in raising the next generation carries eternal significance, as God works through faithful parenting and mentoring to accomplish His purposes across generations.

This truth from Scripture isn''t meant to simply inform us—it''s meant to transform us. God''s Word always calls us to action, to a life that reflects His character and purposes.

Consider how this principle applies to your life right now. Where is God inviting you to grow? What step of obedience is He calling you to take? The beauty of Scripture is that it speaks into every season of life, offering guidance, correction, and encouragement exactly when we need it.

As you reflect on this passage today, ask the Holy Spirit to illuminate areas where you can apply this truth. God''s Word is living and active, sharper than any two-edged sword. Let it do its work in your heart.',
  'Identify one area where you''ve been relying on your own strength instead of God''s, and consciously surrender it to Him today.',
  '"Father, thank You for Your Word and the wisdom found in 1 Chronicles. Help me to not just hear these truths but to live them out. Give me the courage and strength to apply what You''re teaching me today. Transform my heart and renew my mind through Your Spirit. In Jesus'' name, Amen."',
  'New Beginnings: Starting the Year with God',
  'intermediate',
  ARRAY['men', 'general']
);

